public static void check(Solution solution) {
    assert Arrays.equals(solution.executeInstructions(1, new int[]{0,0}, "LRUD"), new int[]{0, 0, 0, 0});
    assert Arrays.equals(solution.executeInstructions(4, new int[]{2,2}, "DDDD"), new int[]{1, 1, 1, 1});
    assert Arrays.equals(solution.executeInstructions(5, new int[]{2,2}, "LUDDRL"), new int[]{6, 5, 4, 3, 2, 1});
    assert Arrays.equals(solution.executeInstructions(4, new int[]{0,3}, "RRRR"), new int[]{0, 0, 0, 0});
    assert Arrays.equals(solution.executeInstructions(3, new int[]{2,0}, "RRU"), new int[]{3, 2, 1});
    assert Arrays.equals(solution.executeInstructions(500, new int[]{250,250}, "LRUD" * 125), Error: Solution.executeInstructions() missing 1 required positional argument: 's');
    assert Arrays.equals(solution.executeInstructions(4, new int[]{1,2}, "LURDLU"), new int[]{6, 5, 4, 3, 2, 1});
    assert Arrays.equals(solution.executeInstructions(4, new int[]{2,2}, "UUDDLLRR"), new int[]{8, 7, 1, 5, 4, 3, 1, 1});
