    console.assert(JSON.stringify(candidate(3, [2,0], "RRU")) === JSON.stringify([3, 2, 1]));
    console.assert(JSON.stringify(candidate(500, [250,250], "LRUD" * 125)) === JSON.stringify(Error: Solution.executeInstructions() missing 1 required positional argument: 's'));
    console.assert(JSON.stringify(candidate(4, [1,2], "LURDLU")) === JSON.stringify([6, 5, 4, 3, 2, 1]));
    console.assert(JSON.stringify(candidate(4, [2,2], "UUDDLLRR")) === JSON.stringify([8, 7, 1, 5, 4, 3, 1, 1]));
    console.assert(JSON.stringify(candidate(3, [0,1], "RRDDLU")) === JSON.stringify([1, 5, 4, 3, 1, 0]));
    console.assert(JSON.stringify(candidate(4, [3,0], "DDDD")) === JSON.stringify([0, 0, 0, 0]));
    console.assert(JSON.stringify(candidate(5, [0,0], "DRDLUR")) === JSON.stringify([6, 5, 1, 0, 0, 1]));
    console.assert(JSON.stringify(candidate(2, [1,1], "LURD")) === JSON.stringify([4, 1, 0, 0]));
    console.assert(JSON.stringify(candidate(5, [3,3], "DDDDRRRRUUUULLLL")) === JSON.stringify([1, 1, 1, 2, 1, 1, 1, 4, 3, 6, 5, 4, 3, 3, 2, 1]));
